def name_operands(region,address,operation):
 if region=='Station' and address==0x67E0:
  for old,new in (('(#67D2)','(@ModelListState.HoverRows)'),('LD A, #24','LD A, @PreviewPriceConst.PriceColumn'),('(#9849)','(@CurrentModels.ShipIndex)'),('(#984A)','(@CurrentModels.SkimmerIndex)'),('LD HL, #94BC','LD HL, @ModelAvailability.Level01')):operation=operation.replace(old,new)
 return operation
